import React, { useMemo } from 'react';
import { MenuItem } from '@/store/menu';
import { Button, Card, Collapse, Grid } from '@arco-design/web-react';
import i18next from 'i18next';
import PageContent from './PageContent';
import store from '../store';
import _ from 'lodash';
import { IconEdit } from '@arco-design/web-react/icon';

const CollapseItem = Collapse.Item;

interface BodyProps {
    list: MenuItem[]
}

const BodyList = ({ list }: BodyProps) => {

    const children = useMemo(() => {
        if(!list.length) return [];
        return list.map((o, i) => {
            if(o.type === "directory"){
                return (
                    <Grid.Col key={i} span={24}>
                        <Collapse bordered={false}>
                            <CollapseItem
                                header={`目录：${o.path}（${i18next.t(o.name)}）`}
                                name={o.id}
                                extra={(
                                    <Button type="primary"
                                        size="small"
                                        icon={<IconEdit />}
                                        onClick={() => {
                                            store.setVisible(true, o);
                                            setTimeout(() => {
                                                store.form.setFieldsValue(_.pick(o,['name', 'path']))
                                            })
                                        }}
                                    />
                                )}
                            >
                                <BodyList list={o.children} />
                            </CollapseItem>
                        </Collapse>
                    </Grid.Col>
                )
            }else if(o.type === "menu"){
                return (
                    <Grid.Col key={i} span={12}>
                        <PageContent item={o} />
                    </Grid.Col>
                )
            }
            return <span key={i}>111</span>
        })
    },[list])

    return (
        <Grid.Row gutter={[8,8]}>
            {children}
        </Grid.Row>
    )
}

export default BodyList;